724: // ── AgenticOrchestrator encounter handler (all modalities) ────────────
725: async function runAgenticEncounter(
726:   encounter: ScheduledEncounter,
727:   sig: Significator,
728:   world: WorldState,
729:   history: ConsequenceRecord[],
730:   responsesPool?: number[],
731:   consecutivePasses?: Map<string, number>,
732:   usedItemIds?: Set<string>,
733: ): Promise<{
734:   outcome: import('../src/core/assessments/AgenticOrchestrator.js').OrchestratorResult;
735:   response: PlayerResponse;
736:   narrativeSummary: string;
737: }> {
738:   const [encLine, encStage] = encounter.moduleRef.split(':') as [Line, Stage];
739:   const modRegistry = (globalThis as any).__moduleRegistry as ModuleRegistry | undefined;
740: 
741:   // If --line/--stage/--modality forcing is active, override the encounter
742:   let forcedEncounter = encounter;
743:   if (FORCE_LINE || FORCE_STAGE || FORCE_MODALITY) {
744:     const forcedLine = FORCE_LINE ?? encLine;
745:     const forcedStage = FORCE_STAGE ?? encStage;
746:     const forcedModality = FORCE_MODALITY ?? encounter.modality;
747:     const forcedModule = modRegistry?.get(forcedLine, forcedStage);
748:     if (forcedModule) {
749:       forcedEncounter = {
750:         ...encounter,
751:         moduleRef: `${forcedLine}:${forcedStage}`,
752:         modality: forcedModality,
753:         targetLines: [forcedLine],
754:         stage: forcedStage,
755:       };
756:     }
757:   }
758: 
759:   const uiHandler: AgenticUIHandler = {
760:     askUser: async (params: AskUserQuestionParams): Promise<AskUserQuestionResult> => {
761:       const answers: UserAnswer[] = [];
762: 
763:       for (const q of params.questions) {
764:         if (!JSON_MODE) {
765:           const mod = forcedEncounter.modality;
766:           const isShadow = forcedEncounter.executionMode === 'shadow';
767:           let modHeader = '';
768: 
769:           switch (mod) {
770:             case 'Deterministic':
771:               modHeader = isShadow
772:                 ? `${chalk.bold.red('◆ [SHADOW TRIAL] ▬▬▬▬▬▬▬▬▬▬▬▬▬░ (9.5s remaining)')}\n`
773:                 : `${chalk.bold.red('⏳ [TIMED TRIAL] ▬▬▬▬▬▬▬▬▬▬▬▬▬░ (9.5s remaining)')}\n`;
774:               break;
775:             case 'LanguageReflective':
776:               modHeader = isShadow
777:                 ? `${chalk.bold.red('◆ [SHADOW REFLECTION] • Confront the unresolved pattern •')}\n`
778:                 : `${chalk.bold.blue('🧘 [REFLECTION BEAT] • Tune in to your inner state •')}\n`;
779:               break;
780:             case 'ScenarioChoice':
781:               modHeader = isShadow
782:                 ? `${chalk.bold.red('◆ [SHADOW CROSSROADS] • The shadow demands a choice •')}\n`
783:                 : `${chalk.bold.yellow('🔀 [DECISION CROSSROADS] • A path diverges •')}\n`;
784:               break;
785:             case 'Embodied':
786:               modHeader = isShadow
787:                 ? `${chalk.bold.red('◆ [SHADOW SCAN] • Feel where the shadow lives in the body •')}\n`
788:                 : `${chalk.bold.green('💓 [SOMATIC SCAN] • Focus on body sensation •')}\n`;
789:               break;
790:             case 'Strategic':
791:               modHeader = isShadow
792:                 ? `${chalk.bold.red('◆ [SHADOW WAR-TABLE] • Map the shadow\'s strategy •')}\n`
793:                 : `${chalk.bold.magenta('♟️ [TACTICAL WAR-TABLE] • Assess constraints •')}\n`;
794:               break;
795:             case 'SocialCooperative':
796:               modHeader = isShadow
797:                 ? `${chalk.bold.red('◆ [SHADOW DIPLOMACY] • Navigate the shadow in relation •')}\n`
798:                 : `${chalk.bold.cyan('🤝 [DIPLOMACY] • Navigating connection •')}\n`;
799:               break;
800:             case 'ImmersiveRPG':
801:               modHeader = isShadow
802:                 ? `${chalk.bold.red('◆ [SHADOW SCENE] • The shadow writes its chapter •')}\n`
803:                 : `${chalk.bold.yellow('📖 [NARRATIVE SCENE] • The story unfolds •')}\n`;
804:               break;
805:             default:
806:               modHeader = isShadow
807:                 ? `${chalk.bold.red('◆ [SHADOW WORK]')}\n`
808:                 : `${chalk.bold.dim('[' + (mod as string).toUpperCase() + ']')}\n`;
809:           }
810: 
811:           console.log(`\n  ${modHeader}  ${chalk.magenta('[' + q.header + ']')}`);
812:           console.log(`  ${chalk.bold(q.question)}`);
813:           if (q.options?.length) {
814:             for (let i = 0; i < q.options.length; i++) {
815:               const opt = q.options[i];
816:               console.log(`    ${chalk.cyan('[' + (i + 1) + ']')} ${opt.label} — ${opt.description}`);
817:             }
818:           }
819:         }
820: 
821:         emitEvent('ask_user', {
822:           header: q.header,
823:           question: q.question,
824:           options: q.options?.map((o, i) => ({ index: i + 1, label: o.label, description: o.description })),
825:           allowWriteIn: q.allowWriteIn,
826:         });
827: 
828:         if (HEADLESS) {
829:           // Use forced responses pool if provided (one index per question, consumed sequentially)
830:           let selectedIdx: number;
831:           if (responsesPool && responsesPool.length > 0) {
832:             const forcedIdx = responsesPool.shift()!;
833:             if (q.options && forcedIdx >= 1 && forcedIdx <= q.options.length) {
834:               selectedIdx = forcedIdx - 1;
835:             } else {
836:               selectedIdx = 0;
837:             }
838:           } else {
839:             // Vary selection to probe different shadow patterns:
840:             // Cycle through options to ensure shadow detection has varied input
841:             const hash = (Date.now() + (q.options?.length ?? 4)) % 4;
842:             selectedIdx = hash < (q.options?.length ?? 4) ? hash : 0;
843:           }
844:           const selectedOpt = q.options?.[selectedIdx];
845:           const selectedLabel = selectedOpt?.label ?? '';
846: 
847:           // Shadow keyword injection for testing — randomly inject (10% chance)
848:           // to allow MOST encounters to pass and demonstrate altitude shifts.
849:           // When FORCE_SHADOW=none, skip injection entirely for clean progression.
850:           const shadowInjections = ['', 'i feel the need to withdraw from this confrontation', 'i must transcend these petty concerns and reach enlightenment', 'i prefer to stay here where it is safe and comfortable'];
851:           const injectShadow = FORCE_SHADOW !== 'none' && selectedIdx > 0 && Math.random() < 0.1;
852:           const writeInShadow = injectShadow ? (shadowInjections[selectedIdx] ?? '') : '';
853: 
854:           if (writeInShadow) {
855:             answers.push({ selectedLabels: [selectedLabel], writeInValue: writeInShadow });
856:           } else {
857:             answers.push({ selectedLabels: [selectedLabel] });
858:           }
859:         } else {
860:           const promptText = q.multiSelect
861:             ? '\n  Select (comma-separated): '
862:             : '\n  Select: ';
863:           const answer = await ask(promptText);
864:           const selections = answer.split(',').map(s => parseInt(s.trim(), 10)).filter(n => !isNaN(n));
865:           const selectedLabels = selections
866:             .filter(n => n >= 1 && n <= (q.options?.length ?? 0))
867:             .map(n => q.options![n - 1]!.label);
868: 
869:           // Determine if input is a simple numeric choice from the options
870:           let isSimpleNumericChoice = false;
871:           if (q.options?.length && answer.trim()) {
872:             const parts = answer.split(',').map(s => s.trim());
873:             isSimpleNumericChoice = parts.every(part => {
874:               const num = parseInt(part, 10);
875:               return !isNaN(num) && String(num) === part && num >= 1 && num <= q.options!.length;
876:             });
877:           }
878: 
879:           if (q.allowWriteIn || (!q.options?.length && answer.trim())) {
880:             // Only populate writeInValue if it's NOT a simple numeric choice
881:             if (!isSimpleNumericChoice && answer.trim()) {
882:               answers.push({ selectedLabels, writeInValue: answer.trim() });
883:             } else {
884:               answers.push({ selectedLabels });
885:             }
886:           } else {
887:             answers.push({ selectedLabels });
888:           }
889:         }
890:       }
891: 
892:       return { answers };
893:     }
894:   };
895: 
896:   // Always route through AgenticOrchestrator — it handles LLM + fallback internally
897:   // Look up the assessment module from the registry to inject into the LLM context
898:   const baseModule = modRegistry?.get(encLine, encStage);
899: 
900:   // Build ConceptDraftIndex from the module registry so the LLM sees module metadata
901:   const conceptModules: Record<string, any> = {};
902:   if (modRegistry) {
903:     for (const m of modRegistry.getAll()) {
904:       const key = `${m.line.toLowerCase()}:${m.stage.toLowerCase()}`;
905:       conceptModules[key] = {
906:         line: m.line,
907:         stage: m.stage,
908:         title: `${m.line} ${m.stage} Module`,
909:         modalities: m.tasks.map(t => t.type === 'llm_dialogue' ? 'LanguageReflective' as const : 'Deterministic' as const),
910:       };
911:     }
912:   }
913: 
914:   const orchestrator = new AgenticOrchestrator({
915:     encounter: forcedEncounter,
916:     significator: sig,
917:     world,
918:     history,
919:     conceptIndex: { modules: conceptModules },
920:     uiHandler,
921:     module: modRegistry?.get(FORCE_LINE ?? encLine, FORCE_STAGE ?? encStage) ?? baseModule,
922:     noLlm: !LLM_ACTIVE,
923:     forceShadow: FORCE_SHADOW,
924:     consecutivePasses,
925:     usedItemIds,
926:   });
927: 
928:   const outcome = await orchestrator.run();
929: 
930:   // Build a PlayerResponse from the orchestrator's consequence record
931:   const cr = outcome.consequenceRecord;
932:   const response: PlayerResponse = {
933:     encounterId: encounter.id,
934:     energeticDirection: cr.polarityTrace.energeticDirection,
935:     driveDirectionality: cr.polarityTrace.driveDirectionality,
936:     stageOrientation: cr.polarityTrace.stageOrientation,
937:     sourceOfNourishment: cr.polarityTrace.sourceOfNourishment,
938:     shadowSurfaced: cr.shadowSurfaced,
939:     shadowResolvedId: cr.shadowResolved,
940:     narrativeSummary: outcome.narrativeSummary,
941:   };
942: 
943:   return { outcome, response, narrativeSummary: outcome.narrativeSummary };
944: }
